const request = $input.first().json;
const body = request.body ?? request;
const errors = [];
const required = ['external_subscription_id', 'wallet_id', 'transaction_id', 'metric_code'];
for (const field of required) {
  if (body[field] === undefined || body[field] === null || String(body[field]).trim() === '') errors.push(field + ' is required');
}
const promptTokens = Number(body.prompt_tokens);
const completionTokens = Number(body.completion_tokens);
if (!Number.isInteger(promptTokens) || promptTokens < 0) errors.push('prompt_tokens must be a non-negative integer');
if (!Number.isInteger(completionTokens) || completionTokens < 0) errors.push('completion_tokens must be a non-negative integer');
const totalTokens = promptTokens + completionTokens;
if (Number.isFinite(totalTokens) && totalTokens <= 0) errors.push('the request must contain at least one token');
const threshold = body.low_credit_threshold === undefined ? 20 : Number(body.low_credit_threshold);
if (!Number.isFinite(threshold) || threshold < 0) errors.push('low_credit_threshold must be a non-negative number');
let timestamp = '';
if (body.timestamp !== undefined && body.timestamp !== null && String(body.timestamp).trim() !== '') {
  const parsed = new Date(body.timestamp);
  if (Number.isNaN(parsed.getTime())) errors.push('timestamp must be a valid ISO-8601 date');
  else timestamp = parsed.toISOString();
}
return [{ json: {
  valid: errors.length === 0,
  errors,
  external_subscription_id: String(body.external_subscription_id ?? '').trim(),
  wallet_id: String(body.wallet_id ?? '').trim(),
  transaction_id: String(body.transaction_id ?? '').trim(),
  metric_code: String(body.metric_code ?? '').trim(),
  prompt_tokens: Number.isFinite(promptTokens) ? promptTokens : 0,
  completion_tokens: Number.isFinite(completionTokens) ? completionTokens : 0,
  total_tokens: Number.isFinite(totalTokens) ? totalTokens : 0,
  model: String(body.model ?? 'unknown').trim() || 'unknown',
  low_credit_threshold: Number.isFinite(threshold) ? threshold : 20,
  timestamp,
}, pairedItem: { item: 0 } }];

const fees = $input.all().map((item) => item.json);
const estimatedAmountCents = fees.reduce((total, fee) => total + Number(fee.amount_cents ?? 0), 0);
if (!Number.isFinite(estimatedAmountCents) || estimatedAmountCents < 0) {
  throw new Error('Lago returned an invalid estimated fee amount');
}
const usage = $('Normalize AI Usage Data').first().json;
return [{ json: { ...usage, estimated_amount_cents: estimatedAmountCents, estimated_fee_count: fees.length } }];

const wallet = $input.first().json;
const usage = $('Total Estimated Fees').first().json;
const creditsBalance = Number(wallet.credits_balance);
const rateAmount = Number(wallet.rate_amount);
if (!Number.isFinite(creditsBalance)) throw new Error('The Lago wallet did not return a numeric credits_balance');
if (!Number.isFinite(rateAmount) || rateAmount <= 0) throw new Error('The Lago wallet did not return a positive rate_amount');
const estimatedCredits = (Number(usage.estimated_amount_cents) / 100) / rateAmount;
const projectedBalance = creditsBalance - estimatedCredits;
return [{ json: {
  ...usage,
  wallet_status: String(wallet.status ?? ''),
  wallet_currency: String(wallet.currency ?? ''),
  credits_balance: creditsBalance,
  rate_amount: rateAmount,
  estimated_credits: estimatedCredits,
  projected_credit_balance: projectedBalance,
  low_credit_alert: projectedBalance <= Number(usage.low_credit_threshold),
} }];
